    private static String score(BigDecimal settled, int overdueCount) {
        return settled.movePointLeft(2).subtract(BigDecimal.valueOf(5L * overdueCount))
                .setScale(0, java.math.RoundingMode.HALF_EVEN).toPlainString();
    }

