package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.batch.SettleBatches;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithClaims {
    public void respond(@PathVariable("sheetId") String sheetId, Claims claims, ClaimLocks locks, SettleBatches batches,
            ObjectResponse<List<ClaimResponse>> response) {
        java.util.Map<Long, List<String>> logs = claims.logs(sheetId.trim());
        java.util.Map<Long, List<String>> comments = claims.comments(sheetId.trim());
        java.util.Map<Long, List<String>> lines = claims.lines(sheetId.trim());
        java.util.Map<Long, java.time.LocalDate> reviewOn = claims.reviewOns(sheetId.trim());
        java.util.Map<Long, String> locked = locks.list(sheetId.trim());
        java.util.Map<Long, Integer> batched = batches.byClaim(sheetId.trim());
        response.send(claims.list(sheetId.trim()).stream()
                .map(c -> ClaimResponse.from(c, logs.getOrDefault(c.id(), List.of())).withLockedBy(locked.get(c.id()))
                        .withComments(comments.getOrDefault(c.id(), List.of())).withBatch(batched.get(c.id()))
                        .withLines(lines.getOrDefault(c.id(), List.of())).withReviewOn(reviewOn.get(c.id())))
                .toList());
    }
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson, RefusedError } from '../../api/http';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { peopleQuery } from '../people/peopleQuery';
import { useUser } from '../session/useUser';
import { claimsKey } from './claimsQuery';
import type { Claim } from './claimsQuery';
import { useClaimError } from './useClaimError';

/**
 * Move the claim to another person on the sheet. Only a role the settings' permission matrix allows (by default a steward) moves a DRAFT, OPEN or PENDING claim; the server
 * refuses anything else, and the refusal shows on the claim (in its shared `claim-error`) until its next action.
 * The moved claim keeps its number and date, is live again until its new person's next statement, and lists first
 * under them.
 */
function ClaimReassign({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const people = (useQuery(peopleQuery(sheetId)).data ?? []).filter((p) => p.id !== claim.personId);
  const [to, setTo] = useState('');
  const [, setError] = useClaimError(claim.id);
  const once = useSubmitOnce();
  const reassign = useMutation({
    mutationFn: (personId: number) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/person`, { personId }, user),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
    onError: (e) => setError(e instanceof RefusedError ? e.message : 'The claim could not be moved.'),
  });

  return (
    <td>
      <select
        data-testid="claim-reassign-to"
        value={to}
        onChange={(e) => {
          setTo(e.target.value);
          setError('');
        }}
      >
        <option value="">Move to…</option>
        {people.map((p) => (
          <option key={p.id} value={p.id}>
            {p.name}
          </option>
        ))}
      </select>
      <button
        type="button"
        data-testid="claim-reassign"
        disabled={reassign.isPending}
        onClick={() => {
          setError('');
          if (!to) {
            setError('Choose a person to move the claim to.');
            return;
          }
          once(() => reassign.mutateAsync(Number(to)));
        }}
      >
        Move
      </button>
    </td>
  );
}

export const contribution = ClaimCells.fill({ order: 30, Component: ClaimReassign });
