6:export class ConflictError extends Error {}
9:export class RefusedError extends Error {}
28:export function getJson<T>(path: string, user?: string): Promise<T> {
37:export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
45:export function putJson<T>(path: string, body: unknown, user?: string): Promise<T> {
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { useSyncExternalStore } from 'react';

// One refusal per claim row, shared by every cell that acts on the claim, so the row shows a single
// `claim-error` and the next action on the row, whichever cell takes it, clears the last one.
const errors = new Map<number, string>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/** Sets a claim's refusal ('' clears it) from outside its row, e.g. a bulk action. */
export function setClaimError(claimId: number, error: string) {
  if ((errors.get(claimId) ?? '') === error) return;
  if (error) errors.set(claimId, error);
  else errors.delete(claimId);
  listeners.forEach((l) => l());
}

/** The claim's refusal ('' when none) and its setter. */
export function useClaimError(claimId: number): [string, (error: string) => void] {
  const error = useSyncExternalStore(subscribe, () => errors.get(claimId) ?? '');
  return [error, (next) => setClaimError(claimId, next)];
}

